reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select auth_user_id from public.ffh_profiles where staff_id='M21954'),'role','authenticated')::text,true);
select public.ffh_governance('save_access','{"staff_id":"QA_MANAGER","designation":"MANAGER","zones":["QA_ZONE_A"],"grants":[{"module":"cpo","can_edit":true},{"module":"income","can_edit":true}]}'::jsonb);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000001001","role":"authenticated"}',true);
select public.ffh_publish_campaigns(public.ffh_campaign_state()||jsonb_build_array(jsonb_build_object('id','QA_CPO','title','QA campaign','sr','ALL','type','CPO','executionMode','view','startDate',(now() at time zone 'Asia/Kuala_Lumpur')::date,'endDate',(now() at time zone 'Asia/Kuala_Lumpur')::date+7)));
do $$begin if not exists(select 1 from jsonb_array_elements(public.ffh_campaign_state()) c where c->>'id'='QA_CPO' and c->'zoneIds' ? 'QA_ZONE_A') then raise exception 'FAIL scoped campaign creation';end if;
 begin perform public.ffh_publish_campaigns((select jsonb_agg(c) from jsonb_array_elements(public.ffh_campaign_state()) c where c->>'id'<>'QA_CPO'));raise exception 'FAIL campaign deletion allowed';exception when insufficient_privilege then null;end;end$$;
