reset role;
do $$begin if exists(select 1 from public.ffh_reward_offers where title='QA scoped offer' and assigned_to not in ('QA_MANAGER','QA_SR_A')) then raise exception 'FAIL offer escaped scope';end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000001003","role":"authenticated"}',true);
do $$begin if exists(select 1 from jsonb_array_elements(public.ffh_campaign_state()) c where c->>'id'='QA_CPO') then raise exception 'FAIL campaign leaked to other zone';end if;if exists(select 1 from jsonb_array_elements(public.ffh_earnings('state')->'offers') c where c->>'title'='QA scoped offer') then raise exception 'FAIL offer leaked to other zone';end if;end$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select auth_user_id from public.ffh_profiles where staff_id='M21954'),'role','authenticated')::text,true);
select public.ffh_publish_campaigns((select jsonb_agg(c) from jsonb_array_elements(public.ffh_campaign_state()) c where c->>'id'<>'QA_CPO'));
select public.ffh_governance('restore',jsonb_build_object('id',(select max(id) from ffh_private.trash where row_key->>'item_id'='QA_CPO')));
do $$begin if not exists(select 1 from jsonb_array_elements(public.ffh_campaign_state()) c where c->>'id'='QA_CPO') then raise exception 'FAIL campaign undo';end if;end$$;
